+func handleUnsupportedAgentHookPolicy(ctx context.Context, errW io.Writer, ag agent.Agent, eventType agent.EventType) (skipHook bool, err error) {
+	repo, err := gitrepo.OpenCurrent(ctx)
+	if err != nil {
