		return nil
	}
	return unsupportedCheckpointPolicyError(policy)
}

func checkpointPolicyForCheckpointData(ctx context.Context, repo *git.Repository) (checkpointpolicy.Policy, error) {
	state, err := checkpointpolicy.ReadLocal(ctx, repo)
	if err != nil {
